CREATE TABLE users (id TEXT PRIMARY KEY, name TEXT NOT NULL, avatar TEXT, access_token TEXT NOT NULL);
CREATE TABLE workspaces (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL UNIQUE REFERENCES users(id), name TEXT NOT NULL DEFAULT 'My community', plan TEXT NOT NULL DEFAULT 'scout', subscription_status TEXT NOT NULL DEFAULT 'free', customer_id TEXT UNIQUE, subscription_id TEXT UNIQUE, guild_id TEXT UNIQUE, guild_name TEXT, alert_channel_id TEXT, created_at INTEGER NOT NULL, alerts_enabled INTEGER NOT NULL DEFAULT 1, failure_threshold INTEGER NOT NULL DEFAULT 1, ban_sharing_enabled INTEGER NOT NULL DEFAULT 0, ban_public_name TEXT NOT NULL DEFAULT '');
CREATE TABLE sessions (token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), csrf TEXT NOT NULL, expires_at INTEGER NOT NULL);
CREATE TABLE oauth_states (state_hash TEXT PRIMARY KEY, expires_at INTEGER NOT NULL);
CREATE TABLE servers (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id), name TEXT NOT NULL, game TEXT NOT NULL CHECK(game IN ('asa','ase')), map TEXT NOT NULL, host TEXT NOT NULL, port INTEGER NOT NULL, password TEXT NOT NULL, max_players INTEGER NOT NULL DEFAULT 70, status TEXT NOT NULL DEFAULT 'unknown', players INTEGER NOT NULL DEFAULT 0, latency INTEGER, last_checked INTEGER, created_at INTEGER NOT NULL, cluster TEXT NOT NULL DEFAULT '', maintenance INTEGER NOT NULL DEFAULT 0, player_list TEXT NOT NULL DEFAULT '[]', notes TEXT NOT NULL DEFAULT '', failed_checks INTEGER NOT NULL DEFAULT 0, failed_since INTEGER);
CREATE TABLE schedules (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id), server_id TEXT NOT NULL REFERENCES servers(id) ON DELETE CASCADE, name TEXT NOT NULL, action TEXT NOT NULL CHECK(action IN ('save','broadcast')), message TEXT NOT NULL DEFAULT '', interval_minutes INTEGER NOT NULL, next_run INTEGER NOT NULL, enabled INTEGER NOT NULL DEFAULT 1, last_run INTEGER, last_status TEXT, last_detail TEXT);
CREATE TABLE activity (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id), server_id TEXT, title TEXT NOT NULL, detail TEXT NOT NULL, level TEXT NOT NULL DEFAULT 'info', created_at INTEGER NOT NULL);
CREATE TABLE metrics (server_id TEXT NOT NULL REFERENCES servers(id) ON DELETE CASCADE, players INTEGER NOT NULL, online INTEGER NOT NULL, created_at INTEGER NOT NULL, latency INTEGER);
CREATE TABLE stripe_events (id TEXT PRIMARY KEY, created_at INTEGER NOT NULL);
CREATE TABLE announcement_templates (id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),name TEXT NOT NULL,body TEXT NOT NULL,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE maintenance_windows (id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),name TEXT NOT NULL,server_ids TEXT NOT NULL,days TEXT NOT NULL,start_time TEXT NOT NULL,duration_minutes INTEGER NOT NULL,time_zone TEXT NOT NULL,enabled INTEGER NOT NULL DEFAULT 1,created_at INTEGER NOT NULL);
CREATE TABLE notifications (id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),title TEXT NOT NULL,detail TEXT NOT NULL,level TEXT NOT NULL,target TEXT NOT NULL,source_key TEXT UNIQUE,created_at INTEGER NOT NULL,read_at INTEGER);
CREATE TABLE incidents (id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),server_id TEXT NOT NULL REFERENCES servers(id) ON DELETE CASCADE,opened_at INTEGER NOT NULL,resolved_at INTEGER,acknowledged_at INTEGER,notes TEXT NOT NULL DEFAULT '');
CREATE TABLE schedule_runs (id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),schedule_id TEXT NOT NULL REFERENCES schedules(id) ON DELETE CASCADE,server_id TEXT NOT NULL REFERENCES servers(id) ON DELETE CASCADE,started_at INTEGER NOT NULL,finished_at INTEGER NOT NULL,status TEXT NOT NULL,detail TEXT NOT NULL);
CREATE TABLE moderation (id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),server_id TEXT NOT NULL REFERENCES servers(id) ON DELETE CASCADE,identifier TEXT NOT NULL,player_name TEXT NOT NULL,action TEXT NOT NULL,reason TEXT NOT NULL,actor TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL, identity_kind TEXT NOT NULL DEFAULT 'game', identity_key TEXT);
CREATE TABLE hosting_connections (server_id TEXT PRIMARY KEY REFERENCES servers(id) ON DELETE CASCADE,workspace_id TEXT NOT NULL REFERENCES workspaces(id),provider TEXT NOT NULL,origin TEXT NOT NULL,remote_id TEXT NOT NULL,api_key TEXT NOT NULL,verified_at INTEGER NOT NULL);
CREATE TABLE ban_directory_reports (id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),server_id TEXT NOT NULL REFERENCES servers(id) ON DELETE CASCADE,identity_key TEXT NOT NULL,identity_kind TEXT NOT NULL,active INTEGER NOT NULL,first_reported_at INTEGER NOT NULL,last_updated_at INTEGER NOT NULL,withdrawn_at INTEGER,UNIQUE(server_id,identity_key));
CREATE TABLE workspace_members (id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),user_id TEXT NOT NULL REFERENCES users(id),role TEXT NOT NULL CHECK(role IN ('admin','moderator','viewer')),server_ids TEXT,created_at INTEGER NOT NULL,UNIQUE(workspace_id,user_id));
CREATE TABLE team_invitations (id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),discord_user_id TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('admin','moderator','viewer')),server_ids TEXT,token_hash TEXT NOT NULL UNIQUE,created_at INTEGER NOT NULL,expires_at INTEGER NOT NULL,accepted_at INTEGER,revoked_at INTEGER);
CREATE TABLE session_workspaces (token_hash TEXT PRIMARY KEY REFERENCES sessions(token_hash) ON DELETE CASCADE,workspace_id TEXT NOT NULL REFERENCES workspaces(id));
CREATE TABLE staff_audit (id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),user_id TEXT NOT NULL,actor TEXT NOT NULL,action TEXT NOT NULL,resource_id TEXT,server_id TEXT,created_at INTEGER NOT NULL);
CREATE TABLE player_profiles (id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),identity_key TEXT NOT NULL,identity_kind TEXT NOT NULL,game TEXT NOT NULL,created_at INTEGER NOT NULL,UNIQUE(workspace_id,identity_key,game));
CREATE TABLE player_observations (profile_id TEXT NOT NULL REFERENCES player_profiles(id) ON DELETE CASCADE,server_id TEXT NOT NULL REFERENCES servers(id) ON DELETE CASCADE,display_name TEXT NOT NULL,first_seen INTEGER NOT NULL,last_seen INTEGER NOT NULL,last_checked INTEGER NOT NULL,sightings INTEGER NOT NULL,online INTEGER NOT NULL,PRIMARY KEY(profile_id,server_id));
CREATE TABLE player_notes (id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),profile_id TEXT NOT NULL REFERENCES player_profiles(id) ON DELETE CASCADE,server_id TEXT NOT NULL REFERENCES servers(id) ON DELETE CASCADE,body TEXT NOT NULL,author_id TEXT NOT NULL,author_name TEXT NOT NULL,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
PRAGMA user_version=4;
